<?php
session_start();if(empty($_SESSION['usuario_id'])||($_SESSION['usuario_rol']??'')!=='admin'){header('Location: ../index.php');exit;}require_once __DIR__.'/../backend/conexion.php';
$tot=$pdo->query("SELECT COUNT(*) pedidos,COALESCE(SUM(CASE WHEN estado<>'cancelado' THEN total ELSE 0 END),0) ventas,COALESCE(AVG(CASE WHEN estado<>'cancelado' THEN total END),0) ticket FROM pedidos")->fetch();
$mes=$pdo->query("SELECT DATE_FORMAT(creado_en,'%Y-%m') periodo,COUNT(*) pedidos,SUM(CASE WHEN estado<>'cancelado' THEN total ELSE 0 END) ventas FROM pedidos WHERE creado_en>=DATE_SUB(CURDATE(),INTERVAL 12 MONTH) GROUP BY DATE_FORMAT(creado_en,'%Y-%m') ORDER BY periodo DESC")->fetchAll();
$top=$pdo->query("SELECT nombre_producto,SUM(cantidad) unidades,SUM(precio_unitario*cantidad) importe FROM pedido_detalles d JOIN pedidos p ON p.id=d.pedido_id WHERE p.estado<>'cancelado' GROUP BY d.producto_id,nombre_producto ORDER BY unidades DESC LIMIT 10")->fetchAll();
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reportes</title><style>body{font:15px Arial;background:#f4f6f8;margin:0}.top{background:#17191d;color:white;padding:18px 5%}.top a{color:white;margin-right:15px}.wrap{max-width:1100px;margin:28px auto;padding:0 18px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.card,section{background:white;padding:18px;border-radius:12px;margin:16px 0}.card b{display:block;font-size:26px;margin-top:8px}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:10px;border-bottom:1px solid #eee}@media(max-width:650px){.grid{grid-template-columns:1fr}}</style></head><body><header class="top"><b>Mi Store · Reportes</b>　<a href="index.php">Panel</a><a href="pedidos.php">Pedidos</a></header><main class="wrap"><h1>Reportes de ventas</h1><div class="grid"><div class="card">Pedidos registrados<b><?=$tot['pedidos']?></b></div><div class="card">Ventas no canceladas<b>S/ <?=number_format($tot['ventas'],2)?></b></div><div class="card">Ticket promedio<b>S/ <?=number_format($tot['ticket'],2)?></b></div></div><section><h2>Ventas por mes</h2><table><tr><th>Mes</th><th>Pedidos</th><th>Ventas</th></tr><?php foreach($mes as $r):?><tr><td><?=htmlspecialchars($r['periodo'])?></td><td><?=$r['pedidos']?></td><td>S/ <?=number_format($r['ventas'],2)?></td></tr><?php endforeach?></table></section><section><h2>Productos más vendidos</h2><table><tr><th>Producto</th><th>Unidades</th><th>Importe</th></tr><?php foreach($top as $r):?><tr><td><?=htmlspecialchars($r['nombre_producto'])?></td><td><?=$r['unidades']?></td><td>S/ <?=number_format($r['importe'],2)?></td></tr><?php endforeach?></table><p><button onclick="window.print()">Imprimir / Guardar como PDF</button></p></section></main></body></html>
